import math

def is_power_of_5(N):
    """Checks if N is a positive integer power of 5."""
    if N <= 0:
        return False
    if N == 1:
        # 5^0 = 1. While the problem implies k >= 1 due to constraints, 
        # we check for mathematical correctness. Since 2^n-3 must be >= 5 (for n=3), 
        # 1 should not occur here, but safe to include.
        return True 

    while N > 1:
        if N % 5 != 0:
            return False
        N //= 5
    return True

N_values = [19, 23, 27]
results = {}

for n in N_values:
    X = (2**n) - 3
    is_pow5 = is_power_of_5(X)
    results[n] = {
        "value": X,
        "is_power_of_5": is_pow5
    }

# Print results in a readable format
print("--- Results ---")
for n, data in results.items():
    # Display the value potentially large number format
    value_str = f"{data['value']:,}" if data['value'] > 10**15 else str(data['value'])
    print(f"For n={n}: 2^{n} - 3 = {value_str}")
    print(f"Is it a power of 5? {data['is_power_of_5']}")
